{"cards": [{"node_code": "N_d3e6fa697f55b748", "definition": "研究利用数值模拟（CFD）和物理实验手段获取流体流动数据、验证理论及分析流动现象的方法学分支。", "boundary": "聚焦于流体力学问题的求解手段与验证技术。涵盖数值离散方法（有限体积、元、谱）、网格生成、求解器算法、收敛性验证，以及实验中的流场可视化、测速（如PIV）和压力测量技术。与“黏性流动与湍流”的区别在于：本节点关注“如何计算/测量”，而非流动本身的物理机理；与“管流、流量与流场参数”的区别在于：本节点侧重通用方法论，兄弟节点侧重特定几何下的参数表征。", "includes": ["数值方法：有限体积法、有限元法、谱方法及其在流体问题中的应用", "数值实施：网格生成策略、离散格式、求解算法、网格无关性与验证", "实验技术：流场显示技术、粒子图像测速（PIV）、激光多普勒测速及压力测量"], "excludes": ["具体的湍流模型推导或边界层理论分析（归入黏性流动与湍流）", "特定管道或管路的流量计算与阻力系数（归入管流、流量与流场参数）"], "sibling_distinctions": [{"other_code": "N_73fff33627b24877", "rule": "本节点收录求解流动问题的数值与实验方法；兄弟节点收录流动的物理机制、湍流模型及黏性效应理论。"}, {"other_code": "N_62c655a8d2497cec", "rule": "本节点侧重通用的计算与测量方法论；兄弟节点侧重管内流动的具体参数（如流量、压降）及流场特征描述。"}], "cross_boundary_rule": "若内容涉及具体湍流模型（如k-epsilon）的数学推导，主挂载至“黏性流动与湍流”；若涉及该模型在CFD软件中的离散实现、网格敏感性分析或实验验证，主挂载至本节点。"}, {"node_code": "N_1f3748b74e1a31d6", "definition": "研究液体中气泡生成、演化、溃灭及其对固体表面损伤（汽蚀）的机理、动力学过程及评价方法的分支。", "boundary": "聚焦于气液两相流中气泡的特殊动力学行为及其工程后果。涵盖空化数、气泡生长与溃灭动力学、微射流冲击、声空化、汽蚀损伤机理及寿命预测。与“黏性流动与湍流”的区别在于：本节点特指涉及相变（气液转换）的流动现象；与“计算与实验流体力学”的区别在于：本节点侧重空化/汽蚀这一特定物理现象的机理与评价，而非通用的求解方法。", "includes": ["空化现象机理：空化数、气泡成核、生长、迁移与溃灭过程", "汽蚀损伤：气泡溃灭对材料表面的冲击、剥蚀机理及寿命评估", "相关应用：泵、螺旋桨、水轮机中的空化性能分析与抑制"], "excludes": ["不涉及相变的单相流体湍流或层流分析（归入黏性流动与湍流）", "通用的CFD数值算法或实验测速技术本身（归入计算与实验流体力学）"], "sibling_distinctions": [{"other_code": "N_73fff33627b24877", "rule": "本节点特指涉及气液相变的空化/汽蚀现象；兄弟节点涵盖更广泛的单相或两相黏性流动及湍流理论，不特指相变损伤。"}, {"other_code": "N_d3e6fa697f55b748", "rule": "本节点侧重空化/汽蚀的物理机理与工程评价；兄弟节点侧重用于研究这些现象的通用数值与实验工具。"}], "cross_boundary_rule": "若研究重点在于气泡溃灭产生的压力场对材料表面的疲劳损伤模型，主挂载至本节点；若重点在于模拟气泡溃灭过程的数值算法改进，主挂载至“计算与实验流体力学”。"}, {"node_code": "N_779a8bff08bea9e1", "definition": "研究高速射流的形成、控制、混合及利用流体动量进行能量传递或控制的元件与技术的分支。", "boundary": "聚焦于射流（Jet）这一特定流动形态及其工程应用。涵盖射流结构、射流控制（如合成射流、等离子体射流）、射流混合、射流泵、射流阀及利用射流原理的流控元件。与“管流、流量与流场参数”的区别在于：本节点侧重开放或受限空间中的射流行为及主动/被动控制；与“计算与实验流体力学”的区别在于：本节点侧重射流这一特定对象的应用与控制，而非通用方法。", "includes": ["射流基础：自由射流、受限射流、射流混合与卷吸机理", "射流控制：利用射流改变主流场、减阻、增混或产生推力", "流控元件：射流泵、射流阀、文丘里管等基于射流原理的装置"], "excludes": ["封闭管道内的稳态或瞬态流动参数计算（归入管流、流量与流场参数）", "通用的CFD求解器开发或实验测速仪原理（归入计算与实验流体力学）"], "sibling_distinctions": [{"other_code": "N_62c655a8d2497cec", "rule": "本节点侧重射流（通常指从孔口或喷嘴喷出）的流动特性与控制应用；兄弟节点侧重封闭管道内的流动参数及流场分布。"}, {"other_code": "N_d3e6fa697f55b748", "rule": "本节点侧重射流现象的工程应用与控制策略；兄弟节点侧重研究射流等流动现象所采用的通用数值与实验方法。"}], "cross_boundary_rule": "若研究内容为射流泵的效率计算或结构优化，主挂载至本节点；若研究内容为射流泵内部流动的CFD网格划分策略，主挂载至“计算与实验流体力学”。"}]}
